{
  "title": "Annual Rainfall Analysis",
  "body": "<div class="rainfall-card">
  <div class="media-section">
    <ml-embed ref="@tool:3fa9c21:out"></ml-embed>
    <div class="caption">Figure 1. Monthly precipitation distribution across the year.</div>
  </div>
  <div class="metrics-section">
    <div class="metric-box total-box">
      <span class="metric-label">Yearly Total</span>
      <span id="total-val" class="metric-value">—</span>
    </div>
    <div class="wettest-section">
      <div class="subheading">Three Wettest Months</div>
      <ol id="top-months-list" class="wettest-list"></ol>
    </div>
  </div>
</div>",
  "css": ".rainfall-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: #ffffff;
  color: #1e293b;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.media-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.caption {
  font-size: 0.85rem;
  color: #64748b;
  text-align: center;
  font-style: italic;
}
.metrics-section {
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 16px;
}
.metric-box {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-bottom: 12px;
  border-bottom: 1px solid #e2e8f0;
}
.metric-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: #334155;
}
.metric-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: #0284c7;
}
.wettest-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.subheading {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #475569;
}
.wettest-list {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.wettest-list li {
  color: #334155;
  font-size: 0.9rem;
}
.list-item-content {
  display: flex;
  justify-content: space-between;
  padding-right: 4px;
}
.month-name {
  font-weight: 500;
}
.month-rain {
  font-weight: 600;
  color: #0369a1;
}",
  "scripts": [
    "const csvText = ml.dereference("@tool:7be01d4:out");
if (csvText) {
  const lines = csvText.trim().split("\n").map(line => line.trim()).filter(line => line.length > 0);
  const dataLines = lines.slice(1);
  const parsed = dataLines.map(line => {
    const parts = line.split(",");
    return {
      month: parts[0]?.trim() ?? "",
      mm: Number(parts[1]?.trim() || 0)
    };
  });

  const total = parsed.reduce((sum, item) => sum + item.mm, 0);
  const totalFormatted = (Math.round(total * 10) / 10).toString();

  const sorted = [...parsed].sort((a, b) => b.mm - a.mm);
  const top3 = sorted.slice(0, 3);

  const totalNode = root.byId["total-val"];
  if (totalNode) {
    totalNode.text = `${totalFormatted} mm`;
  }

  const listNode = root.byId["top-months-list"];
  if (listNode) {
    listNode.children = top3.map(item => ({
      tag: "li",
      attrs: {},
      children: [
        {
          tag: "span",
          attrs: { class: "list-item-content" },
          children: [
            { tag: "span", attrs: { class: "month-name" }, text: item.month },
            { tag: "span", attrs: { class: "month-rain" }, text: `${item.mm} mm` }
          ]
        }
      ]
    }));
  }
}"
  ]
}
